"""Generate out/w2-rB.workflow.json (Brief B on top of Brief A)."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
HOLIDAYS = ["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"]


def api_tool(name, desc, body_props, required, pre=None, post=None, mapping=None, retries=0):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": f"{BASE}/{name}"},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


# ---------------------------------------------------------------- hooks
VARS_HELPER = """
def _vars():
    try:
        return vars
    except Exception:
        return {}
"""

POST_COMMON = """
def _data(result):
    if isinstance(result, dict):
        result.pop('header', None)
        d = result.get('data')
        if isinstance(d, dict):
            return d
        d = {}
        result['data'] = d
        return d
    return {}
def _ok(d):
    return str(d.get('ok')).lower() == 'true'
"""

CLOSE_PRE = VARS_HELPER + """
try:
    V = _vars()
    b = config.get('body')
    if isinstance(b, dict):
        out = str(b.get('outcome') or '')
        tq = str(V.get('st_transfer_queue') or '')
        qmap = {'restructuring': 'restructuring', 'support': 'support', 'general': 'human'}
        if tq in qmap:
            b['outcome'] = 'transferred'
            b['reason'] = qmap[tq]
        elif out in ('promise', 'paid', 'no_promise'):
            n_prom = int(str(V.get('st_promises_ok') or '0'))
            notes = str(V.get('st_notes') or '')
            order = str(V.get('product_order') or '').split(',')
            nd = {}
            for item in notes.split(';'):
                if ':' in item:
                    k, v = item.split(':', 1)
                    if k not in nd:
                        nd[k] = v
            if n_prom > 0:
                b['outcome'] = 'promise'
            elif nd:
                first = ''
                for pid in order:
                    if pid in nd and nd[pid] != 'paid':
                        first = nd[pid]
                        break
                if not first:
                    for k, v in nd.items():
                        if v != 'paid':
                            first = v
                            break
                if first:
                    b['outcome'] = 'no_promise'
                    b['reason'] = first
                else:
                    b['outcome'] = 'paid'
        if b.get('outcome') in ('promise', 'paid'):
            b.pop('reason', None)
except Exception:
    pass
"""

CLOSE_POST = POST_COMMON + """
try:
    d = _data(result)
    if _ok(d):
        d['what_to_do_next'] = 'The call is closed. Say nothing more.'
    else:
        d['what_to_do_next'] = 'Closing failed. Call close_call again with the same outcome and reason.'
except Exception:
    pass
"""

VERIFY_PRE = VARS_HELPER + """
import re
MONTHS = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6, 'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}
def _year(y):
    y = int(y)
    if y < 100:
        y = 1900 + y if y > 30 else 2000 + y
    return y
def _norm(a):
    s = str(a).strip()
    if re.match(r'^[0-9]{4}-[0-9]{2}-[0-9]{2}$', s):
        return s
    low = s.lower()
    nums = re.findall(r'[0-9]+', low)
    mon = 0
    for w in re.findall(r'[a-z]+', low):
        if w[:3] in MONTHS and not (w[:3] == 'mar' and w not in ('mar', 'march')) and not (w[:3] == 'may' and w != 'may'):
            mon = MONTHS[w[:3]]
            break
    if mon and len(nums) >= 2:
        y = [n for n in nums if len(n) == 4]
        dd = [n for n in nums if len(n) <= 2]
        if y and dd:
            return '%04d-%02d-%02d' % (_year(y[0]), mon, int(dd[0]))
    if not mon and len(nums) == 3:
        if len(nums[0]) == 4:
            return '%04d-%02d-%02d' % (int(nums[0]), int(nums[1]), int(nums[2]))
        return '%04d-%02d-%02d' % (_year(nums[2]), int(nums[1]), int(nums[0]))
    if not mon and len(nums) == 1 and len(nums[0]) == 8:
        n = nums[0]
        return '%s-%s-%s' % (n[4:], n[2:4], n[:2])
    return s
try:
    V = _vars()
    b = config.get('body')
    if isinstance(b, dict):
        f = str(b.get('field') or '')
        V['vi_last_field'] = f
        if f == 'date_of_birth':
            b['answer'] = _norm(b.get('answer'))
        elif f == 'phone_last4':
            digits = re.sub(r'[^0-9]', '', str(b.get('answer') or ''))
            if len(digits) >= 4:
                b['answer'] = digits[-4:]
except Exception:
    pass
"""

VERIFY_POST = POST_COMMON + VARS_HELPER + """
try:
    V = _vars()
    field = str(V.get('vi_last_field') or '')
    d = _data(result)
    left = d.get('wrong_answers_left')
    if str(d.get('all_verified')).lower() == 'true':
        d['what_to_do_next'] = 'Both answers are verified. Say a short thank you.'
    elif d.get('hint') == 'day_month_swapped':
        d['what_to_do_next'] = 'The day and month look swapped. This does not count as a wrong answer. Ask the customer to say their date of birth again with the month as a word, for example 14 March 1988.'
    elif not _ok(d) and str(d.get('verified')).lower() != 'false':
        d['what_to_do_next'] = 'The answer could not be read, nothing was counted. Ask for the same answer again clearly (a date of birth with the month as a word).'
    elif str(d.get('verified')).lower() == 'true':
        d['what_to_do_next'] = 'Correct. Now ask the next security question: the last four digits of the phone number on file.'
    elif left is not None and str(left) != '' and int(str(left)) <= 0:
        d['what_to_do_next'] = 'Third wrong answer: the check has failed. Do NOT mention any amount, product or debt. Tell the customer to use the Freya Bank mobile app or visit a branch, thank them and say goodbye, then call close_call with outcome not_verified and reason failed.'
