def code_node(name, code, nxt):
    return {
        "name": name,
        "node_type": "code",
        "passthrough": True,
        "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"},
        "disable_inactivity_monitor": True,
        "pre_actions": [{
            "type": "function",
            "function": {
                "name": "code_exec",
                "handler": "__function__:code_exec",
                "parameters": {"type": "object", "properties": {
                    "code": {"type": "string", "default": code},
                    "timeout_ms": {"type": "number", "default": 10000}}},
            },
        }],
        "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


def grp(*conds):
    return {"logic": "or", "conditions": list(conds)}


def eq(v, o):
    return {"variable": v, "operator": "equals", "operand": o}


CLOSED = {"target_node": "hang_up", "description": "The call was closed",
          "condition": grp(eq("close_call_response.data.ok", "true"), eq("close_call_response.data.ok", "True"))}

