        else:
            name = 'personal loan'
            floor = p.get('instalment_amount')
            floor_name = 'instalment amount'
        dl_days = int(float(str(p.get('days_late') or 0)))
        past = p.get('past_due')
        if dl_days <= 7:
            band = 'early'
            deadline = nth_bday(today, 12)
            attempts = 1
        else:
            band = 'late'
            deadline = nth_bday(today, 7)
            attempts = 2
        a1_amount_full = money(past)
        a1_date = lbw if lbw <= deadline else deadline
        order.append(pid)
        dmap.append(pid + ':' + deadline.isoformat())
        sentences.append('Your ' + name + ' has a past-due amount of ' + money(past) + ' and is ' + str(dl_days) + ' days late.')
        s = ('PRODUCT ' + str(i + 1) + ': product_id ' + pid + ' = "' + name + '". Past-due (full) amount ' + money(past) + '. ' + str(dl_days) + ' days late, ' + band + ' band. '
             'Floor (' + floor_name + ') ' + money(floor) + '. Deadline (latest allowed promise date) ' + say(deadline) + ' = ' + deadline.isoformat() + '. '
             'Persuasion attempts available: ' + str(attempts) + '. '
             'Attempt 1 offer: ' + a1_amount_full + ' (or the floor ' + money(floor) + ' if the customer already said the full amount is too much) on ' + say(a1_date) + ' = ' + a1_date.isoformat() + '. ')
        if attempts == 2:
            s += 'Attempt 2 offer: the floor ' + money(floor) + ' on the deadline ' + say(deadline) + ' = ' + deadline.isoformat() + '. '
        else:
            s += 'No attempt 2 for this product. '
        s += 'A promise amount must be between ' + money(floor) + ' and ' + money(past) + ' inclusive.'
        lines.append(s)
    n = len(prods)
    if n == 1:
        ask = 'Can you make this payment today?'
    elif n == 2:
        ask = 'Can you pay both of them today?'
    else:
        ask = 'Can you pay all ' + str(n) + ' of them today?'
    vars['disclosure_text'] = ('Thank you, that is verified. I am calling from the collections team about a late payment. ' + ' '.join(sentences) + ' ' + ask)
    vars['product_facts'] = '\\n'.join(lines)
    vars['product_count'] = str(n)
    vars['product_order'] = ','.join(order)
    vars['deadline_map'] = ','.join(dmap)
    cal = []
    d = today
    maxdl = max([nth_bday(today, 12)] + [today])
    end = maxdl + datetime.timedelta(days=10)
    while d <= end:
        if d.isoformat() in HOL:
            st = 'BANK HOLIDAY, not a business day'
        elif d.weekday() >= 5:
            st = 'weekend, not a business day'
        else:
            st = 'business day'
        tag = ' (TODAY)' if d == today else ''
        cal.append('- ' + say(d) + ' ' + str(d.year) + ' = ' + d.isoformat() + ': ' + st + tag)
        d = d + datetime.timedelta(days=1)
    vars['calendar_text'] = '\\n'.join(cal)
    mon = today - datetime.timedelta(days=today.weekday())
    rel = []
    for k in range(5):
        a = mon + datetime.timedelta(days=k)
        b = a + datetime.timedelta(days=7)
        rel.append('"this ' + WD[k] + '" = ' + a.isoformat() + ('  (in the past)' if a < today else '') + '; "next ' + WD[k] + '" = ' + b.isoformat())
    vars['relative_days'] = '\\n'.join(rel)
    vars['account_state'] = 'ok' if n > 0 else 'empty'
except Exception as e:
    vars['disclosure_text'] = 'Thank you, that is verified. I am calling from the collections team about a late payment.'
    vars['product_facts'] = 'The account details could not be loaded.'
    vars['product_count'] = '0'
    vars['product_order'] = ''
    vars['deadline_map'] = ''
    vars['calendar_text'] = ''
    vars['relative_days'] = ''
    vars['account_state'] = 'error'
""" % json.dumps(HOLIDAYS)


def code_node(name, code, nxt):
    return {
        "name": name,
        "node_type": "code",
        "passthrough": True,
        "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"},
        "disable_inactivity_monitor": True,
        "pre_actions": [{
            "type": "function",
            "function": {
                "name": "code_exec",
                "handler": "__function__:code_exec",
                "parameters": {"type": "object", "properties": {
                    "code": {"type": "string", "default": code},
                    "timeout_ms": {"type": "number", "default": 10000}}},
            },
        }],
        "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


def grp(*conds):
    return {"logic": "or", "conditions": list(conds)}


def eq(v, o):
    return {"variable": v, "operator": "equals", "operand": o}


CLOSED = {"target_node": "hang_up", "description": "The call was closed",
          "condition": grp(eq("close_call_response.data.ok", "true"), eq("close_call_response.data.ok", "True"))}

